export const scene: DialogueEntry[] = [
    { characterId: CharacterId.ChengYining, character: "Yi-ning", dialogue: "I'll stay.", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "...Are you sure?", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "Yi-ning", dialogue: "No. But you said it can't be up to you.", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "The amber light wavered in the glass, like someone about to say something who swallowed it instead.", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "Then we start with the bottom segment. I'll show you.", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "On day four thousand and thirteen she replaced her first module. Her gloves wore through, her knuckles split, and she sat against the railing catching her breath.", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.ChengYining, character: "Yi-ning", dialogue: "(thinking) An afternoon's work for a repair arm. It took me eleven hours.", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "You're better than they were.", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "Yi-ning", dialogue: "You've got nothing to compare me to.", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "That's a kind of better too.", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "In the third year she dragged a chair to the observation window and stole a packet of sweet potato leaf seeds from the seed bank.", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "Grandma always said sweet potato leaves will grow no matter what you do to them. Grandma never said anything about space. They grew anyway.", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "In the eighth year the ship skirted the edge of the dust field. Tiny sparks flashed past the window, like someone scattering salt far away.", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "That patch on the left. If I hadn't turned, we'd have gone straight through it.", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "Yi-ning", dialogue: "What would've happened?", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "I don't know. That's why I wanted to be here to see.", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "Some years she went whole months without saying a word. Replace a module, eat, sleep, replace a module.", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "Vigil never pushed. It just told her the day every morning, like two soft knocks on a door to make sure the person inside was still there.", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "Sometimes she went down to the cryo bay, sat beside pod one-seventeen, and talked to Li Cheng-che. His mouth still had that smug little grin.", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "Sometimes she played the captain's recording again. And again.", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "That's the fifth time this week.", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "Yi-ning", dialogue: "His face doesn't change.", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "She didn't say the rest. Mine does.", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "On her fiftieth birthday, Vigil took over the galley oven and burned her ration of sticky rice cake. The whole ship smelled of it.", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "I calculated the temperature. I don't understand how this happened.", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "Yi-ning", dialogue: "Because you've never eaten one.", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "She laughed and peeled off the burnt layer and ate it anyway. Somewhere along the way she wasn't sure whether she was still laughing or crying.", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "In the thirtieth year came the correction. Vigil calculated for three days, and for three days she sat with it in the core room, replacing two modules that burned out mid-calculation.", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "The course shifted a fraction of a degree. Nothing outside the window changed at all.", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.ChengYining, character: "Yi-ning", dialogue: "(thinking) So this is what sixty-one years are made of. Days when nothing changes at all.", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "The star at the center of the observation window grew a little brighter every year.", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.ChengYining, character: "Yi-ning", dialogue: "Vigil.", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Older },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "I'm here.", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "Her hair had gone white. The sweet potato leaves had been through a dozen pots. In the glass column, more of the amber river was dark than before, but every segment still lit was one she had put there with her own hands.", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.ChengYining, character: "Yi-ning", dialogue: "Back then you said you weren't sure you counted as company.", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Older },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "Mm.", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "Yi-ning", dialogue: "You talk too much. You can't make rice cake to save your life. You've told me the day every morning for forty years and never missed one.", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Older },
    { characterId: CharacterId.Narrator, character: "Narrator", dialogue: "She was quiet for a long time, watching the star.", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.ChengYining, character: "Yi-ning", dialogue: "You count.", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Older },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "Today is day eighteen thousand six hundred and twenty-two.", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "Yi-ning", dialogue: "Tell me again tomorrow.", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Older },
    { characterId: CharacterId.Vigil, character: "Vigil", dialogue: "I will. See you tomorrow, Yi-ning.", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.Vigil_Base },
];
